use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// Hosts this node's `with` clause grants. Checked before every request so that
/// an out-of-scope URL becomes a recorded failure instead of a boundary trap.
/// The host-side allowlist remains the enforcing check.
const ALLOWED_HOSTS: &[&str] = &[
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

struct Node;

/// Returns the lowercase host of an http or https URL, or None if the URL
/// is not one. Userinfo is dropped so that `https://allowed@evil.example/`
/// yields `evil.example`, and the port is dropped from the host.
fn host_of(url: &str) -> Option<String> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority = rest
        .split(|c: char| c == '/' || c == '?' || c == '#')
        .next()?;
    let host_port = authority.rsplit('@').next()?;
    if host_port.starts_with('[') {
        return None;
    }
    let host = host_port.split(':').next()?;
    if host.is_empty() {
        return None;
    }
    Some(host.to_ascii_lowercase())
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            let allowed = host_of(&url)
                .map(|h| ALLOWED_HOSTS.contains(&h.as_str()))
                .unwrap_or(false);

            if !allowed {
                failures.push(FetchFailure {
                    url,
                    error: "host outside this node's allowlist".to_string(),
                });
                continue;
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
